def fit(t, w, sz=8.0, f=_FR):
    while f.text_length(t, fontsize=sz) > w - 8 and sz > 6.2: sz -= 0.25
    return sz


def wrap(t, w, sz, f=_FR):
    words = t.split(); lines = ['']
    for wd in words:
        c = (lines[-1] + ' ' + wd).strip()
        if f.text_length(c, fontsize=sz) <= w - 8: lines[-1] = c
        else: lines.append(wd)
    return lines


def _cols(spec, X0, X1):
    total = sum(w for _, w in spec); k = (X1 - X0) / total; cols = [(h, w * k) for h, w in spec]
    xs = [X0]
    for _, w in cols: xs.append(xs[-1] + w)
    return cols, xs


def _table(sh, title, rows, y, cols, xs, X0, X1, sz=7.5, lh=8.9):
    sh.text(X0, y, title, 10.5, bold=True, spacing=0.8, raw=True); y += 8
    sh.line((X0, y), (X1, y), 0.8, INK); y += 13
    for (h, w), x in zip(cols, xs): sh.text(x + 4, y, h, 7.25, MID, bold=True, spacing=0.3, raw=True)
    y += 6; sh.line((X0, y), (X1, y), 0.5, INK)
    for r in rows:
        cells = [wrap(str(c), w, sz) for c, (_, w) in zip(r, cols)]
        n = max(len(c) for c in cells); rh = 4.0 + lh * n
        for c, x in zip(cells, xs):
            for j, ln in enumerate(c):
                col = MID if V in ln and ln.strip().startswith(V) else INK
                sh.text(x + 4, y + 9.5 + lh * j, ln, sz, col, serif=(x == xs[0]), raw=True)
        y += rh; sh.line((X0, y), (X1, y), 0.3, LIGHT)
    return y + 16


def _numbered(sh, x, y, w, title, items, sz=7.5):
    sh.text(x, y, title, 10.5, bold=True, spacing=0.8, raw=True); sh.line((x, y + 8), (x + w, y + 8), 0.8, INK)
    y += 24
    for i, t in enumerate(items, 1):
        sh.text(x, y, '%d.' % i, sz, raw=True)
        ls = wrap(t, w - 18, sz)
        for j, ln in enumerate(ls): sh.text(x + 18, y + 9.5 * j, ln, sz, raw=True)
        y += 9.5 * len(ls) + 3.5
    return y


def build():
    doc = fitz.open()
    X0 = 64.0; X1 = TB_X - 28.0
    # ID-002: doors
    sh = Sheet(doc)
    sh.frame('CASA GROVE', '', ['DOOR AND HARDWARE', 'SCHEDULE'], 'ID-002', revisions=(), legend_rule=False)
    cols, xs = _cols(COLS, X0, X1)
    y = 92.0
    sh.text(X0, y, 'DOOR AND HARDWARE SCHEDULE', 16, serif=True, spacing=1.5, raw=True)
    sh.text(X0 + 330, y, 'COORDINATED WITH FOR\'S A-600 REV 1. POOL HOUSE DOORS, WINDOW SCHEDULE AND FOR\'S SECURITY NOTES: ID-003.', 8, MID, raw=True); y += 24
    y = _table(sh, 'FLOOR 1', F1, y, cols, xs, X0, X1)
    y = _table(sh, 'FLOOR 2', F2, y, cols, xs, X0, X1)
    assert y < FR.y1 - 10, ('door tables run off ID-002', y)
    doors_bottom = y
    # ID-003: windows, then the hardware legend, door notes and FOR's security notes
    sh = Sheet(doc)
    sh.frame('CASA GROVE', '', ['WINDOW SCHEDULE, POOL', 'HOUSE DOORS, DOOR NOTES'], 'ID-003', revisions=(), legend_rule=False)
    wc, wx = _cols(WCOLS, X0, X1)
    y = 92.0
    sh.text(X0, y, 'WINDOW SCHEDULE', 16, serif=True, spacing=1.5, raw=True)
    sh.text(X0 + 230, y, 'FOR\'S A-600 REV 1 GOVERNS SIZES, SILLS AND HEADS (OWNER 11.09.26). DOORS: ID-002.', 8, MID, raw=True); y += 24
    y = _table(sh, 'WINDOWS, MAIN HOUSE', WIN, y, wc, wx, X0, X1, sz=7.75, lh=9.4)
    y = _table(sh, 'WINDOWS, POOL HOUSE', WIN_PH, y, wc, wx, X0, X1, sz=7.75, lh=9.4)
    y = _table(sh, 'DOORS, POOL HOUSE', PH, y, cols, xs, X0, X1)
    gap = 34.0; cw = (X1 - X0 - 2 * gap) / 3
    c1, c2, c3 = X0, X0 + cw + gap, X0 + 2 * (cw + gap)
    ya = _numbered(sh, c1, y, cw, 'WINDOW NOTES', WNOTES)
    yb = _numbered(sh, c2, y, cw, 'DOOR NOTES', NOTES)
    yc = _numbered(sh, c3, y, cw, 'FOR\'S SECURITY AND LOCK NOTES (A-600)', SEC)
    yl = max(ya, yb, yc) + 14
    sh.text(X0, yl, 'HARDWARE LEGEND', 10.5, bold=True, spacing=0.8, raw=True); sh.line((X0, yl + 8), (X1, yl + 8), 0.8, INK)
    yl += 24; half = (X1 - X0 - gap) / 2; col_y = [yl, yl]
    for i, (a_, b_) in enumerate(LEGEND):
        k_ = 0 if i < (len(LEGEND) + 1) // 2 else 1; x_ = X0 + k_ * (half + gap); y_ = col_y[k_]
        sh.text(x_, y_, a_, 7.5, bold=True, raw=True)
        ls = wrap(b_, half - 140, 7.5)
        for j, ln in enumerate(ls): sh.text(x_ + 140, y_ + 9.5 * j, ln, 7.5, raw=True)
        col_y[k_] = y_ + 9.5 * len(ls) + 4
    bottom = max(col_y)
    assert bottom < FR.y1 - 10, ('ID-003 runs off the sheet', bottom)
    doc.save(OUT, garbage=4, deflate=True)
    print('saved', OUT, 'door rows', len(F1) + len(F2) + len(PH), 'ID-002 bottom', round(doors_bottom), 'windows', len(WIN), 'ID-003 bottom', round(bottom))


if __name__ == '__main__':
    build()
